/**
 * The records screen (`design/archetypes/list-page.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/list-page.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input } from '@angular/core'

import {
  MEMBER_PROVIDERS,
  Ref,
  Render,
  SlotOutlet,
  SlotTemplate,
  elementRef,
  isTemplate,
  setup,
  useMember,
} from '@polymorph/angular'
import { usePresence } from '@polymorph/angular/motion'
import styles from '@polymorph/recipes/archetypes/list-page.module.css'
import { EmptyState, type EmptyStateProps } from '../structure/EmptyState'
import { Inline, type InlineProps } from '../layout/Inline'
import { PageHeader, type PageHeaderProps } from '../structure/PageHeader'

/** The records screen: the inputs it takes, by the React member's prop names. */
export interface ListPageProps {
  description?: string
  empty?: boolean
  /**
   * The empty state, required so the page always defines what it shows with no records.
   */
  emptyState: EmptyStateProps
  title: string
}

/** The records screen. */
@Component({
  selector: 'pm-list-page',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Ref, Render, SlotOutlet, SlotTemplate, EmptyState, Inline, PageHeader],
  // prettier-ignore
  template: `<ng-template pmSlot="actions" [pmSlotOf]="$"><ng-content select="[slot=actions]" /></ng-template>
<ng-template pmSlot="filters" [pmSlotOf]="$"><ng-content select="[slot=filters]" /></ng-template>
<ng-template pmSlot="summary" [pmSlotOf]="$"><ng-content select="[slot=summary]" /></ng-template>
<ng-template pmSlot="default" [pmSlotOf]="$"><ng-content /></ng-template>
<div
[attr.class]="e1()"
[attr.data-empty]="e2()"
data-member="list-page"
><pm-page-header
[title]="e3()"
[description]="e4()"
>@if (e5()) {<ng-container ngProjectAs="[slot=actions]"><ng-container [pmSlotOutlet]="'actions'" [pmSlotOf]="$" pmSlotInto="actions" /></ng-container>}</pm-page-header>
<ng-container [pmSlotOutlet]="'summary'" [pmSlotOf]="$" />
@if (e6()) {<pm-inline
[gap]="e7()"
[wrap]="e8()"
><ng-container [pmSlotOutlet]="'filters'" [pmSlotOf]="$" pmSlotInto="default" /></pm-inline>}
<div
[attr.class]="e9()"
>@if (e10()) {<div
[attr.class]="e11()"
[pmRef]="records"
><ng-container [pmSlotOutlet]="'default'" [pmSlotOf]="$" /></div>}
@if (e12()) {<div
[attr.class]="e13()"
[pmRef]="nothing"
><pm-empty-state
[icon]="e14()"
[title]="e15()"
[description]="e16()"
>@if (e18()) {<ng-container ngProjectAs="[slot=action]">@if (template(e17())) {<ng-container [pmRender]="e17()" />} @else {{{ e17() }}}</ng-container>}
@if (e20()) {<ng-container ngProjectAs="[slot=secondaryAction]">@if (template(e19())) {<ng-container [pmRender]="e19()" />} @else {{{ e19() }}}</ng-container>}</pm-empty-state></div>}</div></div>`,
})
export class ListPage {
  readonly description = input<ListPageProps['description']>(undefined)
  readonly empty = input<Exclude<ListPageProps['empty'], undefined>, ListPageProps['empty']>(
    false,
    { transform: (value: ListPageProps['empty']) => (value === undefined ? false : value) },
  )
  /**
   * The empty state, required so the page always defines what it shows with no records.
   */
  readonly emptyState = input.required<ListPageProps['emptyState']>()
  readonly title = input.required<ListPageProps['title']>()
  protected readonly $ = useMember({
    events: [],
    props: {
      description: () => this.description(),
      empty: () => this.empty(),
      emptyState: () => this.emptyState(),
      title: () => this.title(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly nothing = elementRef<HTMLElement>()
  protected readonly records = elementRef<HTMLElement>()
  protected readonly recordsPresent = setup(() =>
    usePresence(
      () => !this.$p.empty,
      () => this.records.value,
      'listpage.bodyswap',
    ),
  )
  protected readonly emptyPresent = setup(() =>
    usePresence(
      () => this.$p.empty,
      () => this.nothing.value,
      'listpage.bodyswap',
    ),
  )
  protected readonly template = isTemplate

  protected e1() {
    return styles.page
  }

  protected e2() {
    return this.$p.empty ? '' : undefined
  }

  protected e3(): PageHeaderProps['title'] {
    return this.$p.title
  }

  protected e4(): PageHeaderProps['description'] {
    return this.$p.description
  }

  protected e5() {
    return this.$.filled('actions')
  }

  protected e6() {
    return this.$.filled('filters')
  }

  protected e7(): InlineProps['gap'] {
    if (!this.$.filled('filters')) return undefined as never
    return 3
  }

  protected e8(): InlineProps['wrap'] {
    if (!this.$.filled('filters')) return undefined as never
    return true
  }

  protected e9() {
    return styles.bodySlot
  }

  protected e10() {
    return this.recordsPresent.value()
  }

  protected e11() {
    if (!this.recordsPresent.value()) return undefined as never
    return styles.body
  }

  protected e12() {
    return this.emptyPresent.value()
  }

  protected e13() {
    if (!this.emptyPresent.value()) return undefined as never
    return styles.body
  }

  protected e14(): EmptyStateProps['icon'] {
    if (!this.emptyPresent.value()) return undefined as never
    return this.$p.emptyState.icon
  }

  protected e15(): EmptyStateProps['title'] {
    if (!this.emptyPresent.value()) return undefined as never
    return this.$p.emptyState.title
  }

  protected e16(): EmptyStateProps['description'] {
    if (!this.emptyPresent.value()) return undefined as never
    return this.$p.emptyState.description
  }

  protected e17() {
    if (!this.emptyPresent.value()) return undefined as never
    return this.$p.emptyState.action
  }

  protected e18() {
    if (!this.emptyPresent.value()) return undefined as never
    return this.$p.emptyState.action !== undefined
  }

  protected e19() {
    if (!this.emptyPresent.value()) return undefined as never
    return this.$p.emptyState.secondaryAction
  }

  protected e20() {
    if (!this.emptyPresent.value()) return undefined as never
    return this.$p.emptyState.secondaryAction !== undefined
  }
}
